#include "stdlib/stats/strided/dmadfmsorted.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/stats/strided/dmediansorted.h" // For median calculation
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/constants/float64/pinf.h"
#include "stdlib/constants/float64/ninf.h"
#include "stdlib/math/base/special/abs.h"
#include "stdlib/math/base/special/max.h"
#include "stdlib/math/base/special/min.h"


/**
* Computes the median absolute deviation of a sorted double-precision floating-point strided array.
*
* @param N        number of indexed elements
* @param X        sorted input array
* @param strideX  stride length
* @return         output value (median absolute deviation)
*/
double API_SUFFIX(stdlib_strided_dmadfmsorted)( const CBLAS_INT N, const double *X, const CBLAS_INT strideX ) {
	const CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	return API_SUFFIX(stdlib_strided_dmadfmsorted_ndarray)( N, X, strideX, ox );
}

/**
* Computes the median absolute deviation of a sorted double-precision floating-point strided array using alternative indexing semantics.
*
* @param N        number of indexed elements
* @param X        sorted input array
* @param strideX  stride length
* @param offsetX  starting index for X
* @return         output value (median absolute deviation)
*/
/**
* Computes the median absolute deviation of a sorted double-precision floating-point strided array using alternative indexing semantics.
*/
double API_SUFFIX(stdlib_strided_dmadfmsorted_ndarray)( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	double median;
	double l1, r1, l2, r2;
	CBLAS_INT leftStart, rightStart;
	CBLAS_INT mid1, mid2;
	CBLAS_INT low, high;
	CBLAS_INT n1, n2;
	CBLAS_INT k;
	CBLAS_INT sx = strideX;
	CBLAS_INT ox = offsetX;

	if ( N <= 0 ) {
		return 0.0 / 0.0; // NaN
	}

	median = API_SUFFIX(stdlib_strided_dmediansorted_ndarray)( N, X, sx, ox );
	if ( stdlib_base_is_nan( median ) ) {
		return 0.0 / 0.0;
	}

	if ( sx < 0 ) {
		ox += ( N - 1 ) * sx;
		sx = -sx;
	}

	n1 = N / 2;
	n2 = N - n1;

	leftStart = ox + ( ( n1 - 1 ) * sx );
	rightStart = leftStart + sx;

	k = ( N + 1 ) / 2;
	low = stdlib_base_max( 0, k - n2 );
	high = stdlib_base_min( k, n1 );

	while ( low <= high ) {
		mid1 = ( low + high ) / 2;
		mid2 = k - mid1;

		l1 = ( mid1 <= 0 ) ? STDLIB_CONSTANT_FLOAT64_NINF : stdlib_base_abs( X[ leftStart - ( ( mid1 - 1 ) * sx ) ] - median );
		r1 = ( mid1 >= n1 ) ? STDLIB_CONSTANT_FLOAT64_PINF : stdlib_base_abs( X[ leftStart - ( mid1 * sx ) ] - median );

		l2 = ( mid2 <= 0 ) ? STDLIB_CONSTANT_FLOAT64_NINF : stdlib_base_abs( X[ rightStart + ( ( mid2 - 1 ) * sx ) ] - median );
		r2 = ( mid2 >= n2 ) ? STDLIB_CONSTANT_FLOAT64_PINF : stdlib_base_abs( X[ rightStart + ( mid2 * sx ) ] - median );

		if ( l1 > r2 ) {
			high = mid1 - 1;
		}
		else if ( l2 > r1 ) {
			low = mid1 + 1;
		}
		else {
			if ( N % 2 != 0 ) {
				return stdlib_base_max( l1, l2 );
			}
			return ( stdlib_base_max( l1, l2 ) + stdlib_base_min( r1, r2 ) ) / 2.0;
		}
	}

	return 0.0 / 0.0;
}

